import { existsSync } from 'fs';
import { resolve } from 'path';
import { defineConfig } from 'vite';

const PAGES = ['index', 'about', 'programs', 'enrichments', 'spaces', 'admissions', 'book-a-visit', 'apply-online', 'parents', 'contact', '404'];

// Serve pages at clean URLs locally, the way Cloudflare's asset handling does in
// production: /about serves about.html and /about.html redirects to /about. The Arabic
// pages generated by scripts/build-arabic.mjs live under /ar/ the same way.
function cleanUrls() {
  const middleware = root => (req, res, next) => {
    if (req.method !== 'GET' && req.method !== 'HEAD') return next();
    const [path, query = ''] = req.url.split('?');
    const search = query ? `?${query}` : '';
    const page = path.match(/^\/([a-z0-9-]+)\.html$/i);
    if (page && page[1] !== '404') {
      res.statusCode = 308;
      res.setHeader('Location', (page[1] === 'index' ? '/' : `/${page[1]}`) + search);
      return res.end();
    }
    const arabicPage = path.match(/^\/ar\/([a-z0-9-]+)\.html$/i);
    if (arabicPage && arabicPage[1] !== '404') {
      res.statusCode = 308;
      res.setHeader('Location', `/ar/${arabicPage[1] === 'index' ? '' : arabicPage[1]}${search}`);
      return res.end();
    }
    if (path === '/ar') {
      res.statusCode = 308;
      res.setHeader('Location', `/ar/${search}`);
      return res.end();
    }
    if (path === '/ar/') { req.url = `/ar/index.html${search}`; return next(); }
    const clean = path.match(/^\/((?:ar\/)?[a-z0-9-]+)\/?$/i);
    if (clean && existsSync(resolve(root(), `${clean[1]}.html`))) req.url = `/${clean[1]}.html${search}`;
    next();
  };
  return {
    name: 'clean-urls',
    configureServer(server) { server.middlewares.use(middleware(() => server.config.root)); },
    configurePreviewServer(server) { server.middlewares.use(middleware(() => server.config.build.outDir)); },
  };
}

export default defineConfig({
  plugins: [cleanUrls()],
  build: {
    rollupOptions: {
      input: Object.fromEntries(PAGES.flatMap(page => [
        [page === 'index' ? 'main' : page, resolve(__dirname, `${page}.html`)],
        [`ar-${page}`, resolve(__dirname, `ar/${page}.html`)],
      ])),
    },
  },
});
